// Actifs de marque "Curieux orchestre" (charte graphique 2026, studio Les Alfredines)
// encodes en base64 pour un fonctionnement 100% local, sans dependance reseau.
const UFFICIO_500_B64 = "";
const UFFICIO_900_B64 = "";
const HOST_REGULAR_B64 = "";
const HOST_BOLD_B64 = "";
// Logos : fichiers PNG ordinaires plutôt que base64 en dur. Encodés dans ce
// fichier, ils pesaient 315 Ko transférés sur CHAQUE page (soit 22x le poids
// d'une page), en bloquant l'affichage, et sans pouvoir être mis en cache
// séparément par le navigateur.
const CURIEUX_LOGO_PRUNE_URL   = 'assets/images/logo-prune.png';
const CURIEUX_LOGO_BLANC_URL   = 'assets/images/logo-blanc.png';
const CURIEUX_SYMBOL_PRUNE_URL = 'assets/images/symbole-prune.png';

// jsPDF ne sait pas charger un chemin de fichier : addImage/getImageProperties
// exigent une data-URI, de façon SYNCHRONE (drawCurieuxPdfHeader est appelé au
// milieu de la génération, parfois en boucle sur les sauts de page). On garde
// donc CURIEUX_LOGO_PRUNE_PNG, mais rempli en arrière-plan au chargement au
// lieu d'être écrit en dur : le navigateur a de toute façon déjà ce PNG en
// cache puisqu'il l'affiche en en-tête, la conversion ne coûte donc rien de
// plus. Vaut null tant que le chargement n'est pas fini — les appelants le
// testent déjà (try/catch côté PDF, `if(logoSrc)` côté feuille de route) et se
// contentent alors d'un en-tête sans logo.
let CURIEUX_LOGO_PRUNE_PNG = null;
function preloadCurieuxLogoForPdf(){
  if(CURIEUX_LOGO_PRUNE_PNG || typeof fetch !== 'function') return;
  fetch(CURIEUX_LOGO_PRUNE_URL)
    .then(r => r.ok ? r.blob() : Promise.reject(new Error(String(r.status))))
    .then(blob => new Promise((resolve, reject) => {
      const fr = new FileReader();
      fr.onload = () => resolve(fr.result);
      fr.onerror = reject;
      fr.readAsDataURL(blob);
    }))
    .then(dataUrl => { CURIEUX_LOGO_PRUNE_PNG = dataUrl; })
    .catch(() => {});
}
if(typeof window !== 'undefined') preloadCurieuxLogoForPdf();

function injectCurieuxFonts(){
  if(document.getElementById('curieux-fonts-style')) return;
  const style = document.createElement('style');
  style.id = 'curieux-fonts-style';
  style.textContent = `
    @font-face{
      font-family:'Ufficio Display';
      font-weight:500;
      src:url(data:font/otf;base64,${UFFICIO_500_B64}) format('opentype');
    }
    @font-face{
      font-family:'Ufficio Display';
      font-weight:900;
      src:url(data:font/otf;base64,${UFFICIO_900_B64}) format('opentype');
    }
    @font-face{
      font-family:'Host Grotesk';
      font-weight:400;
      src:url(data:font/ttf;base64,${HOST_REGULAR_B64}) format('truetype');
    }
    @font-face{
      font-family:'Host Grotesk';
      font-weight:700;
      src:url(data:font/ttf;base64,${HOST_BOLD_B64}) format('truetype');
    }
  `;
  document.head.appendChild(style);
}

function applyBrandLogo(){
  const dark = document.documentElement.getAttribute('data-theme') === 'dark';
  const src = dark ? CURIEUX_LOGO_BLANC_URL : CURIEUX_LOGO_PRUNE_URL;
  // Comparaison sur un marqueur et non sur img.src : le navigateur renvoie
  // l'URL absolue résolue, jamais égale au chemin relatif, ce qui ferait
  // réassigner l'image (et clignoter) à chaque appel.
  document.querySelectorAll('.brand-logo-img').forEach(img => {
    if(img.dataset.brandVariant === src) return;
    img.dataset.brandVariant = src;
    img.src = src;
  });
}

// Traduit les messages d'erreur Supabase Auth les plus courants — le reste
// (cas rares) reste affiché tel quel plutôt que de risquer une traduction
// approximative.
const CURIEUX_AUTH_ERROR_FR = {
  'Invalid login credentials': 'Email ou mot de passe incorrect.',
  'User already registered': 'Un compte existe déjà avec cet email.',
  'Password should be at least 6 characters': 'Le mot de passe doit faire au moins 6 caractères.',
  'Unable to validate email address: invalid format': "Format d'email invalide.",
  'Email not confirmed': "Cet email n'a pas encore été confirmé — vérifie ta boîte mail.",
  'For security purposes, you can only request this after some time.': 'Merci de patienter un instant avant de réessayer.',
  'Email rate limit exceeded': "Trop d'emails envoyés en peu de temps (limite du service email intégré à Supabase, quelques envois par heure) — réessaie plus tard, ou configure un fournisseur SMTP dans le projet Supabase pour lever cette limite.",
};
function translateAuthError(message){
  return CURIEUX_AUTH_ERROR_FR[message] || message;
}

function applyCurieuxFavicon(){
  if(document.getElementById('curieux-favicon-link')) return;
  const link = document.createElement('link');
  link.id = 'curieux-favicon-link';
  link.rel = 'icon';
  link.type = 'image/png';
  link.href = CURIEUX_SYMBOL_PRUNE_URL;
  document.head.appendChild(link);
}

// --- Application installable (PWA) ---------------------------------------
// Pose les balises qui font qu'un téléphone reconnaît le site comme une app :
// icône d'écran d'accueil, ouverture en plein écran sans barre de navigateur,
// couleur de l'interface système. Puis enregistre le service worker, qui rend
// les pages déjà visitées consultables hors connexion (voir sw.js).
//
// Ces balises sont posées ici plutôt que recopiées dans les 27 pages : iOS et
// Android lisent le DOM au moment de « Ajouter à l'écran d'accueil », donc
// l'injection au chargement suffit et il n'y a qu'un seul endroit à corriger.
function initCurieuxPWA(){
  if(typeof document === 'undefined' || !document.head) return;
  if(document.getElementById('curieux-pwa-pose')) return;

  const balise = (tag, attrs)=>{
    const el = document.createElement(tag);
    Object.entries(attrs).forEach(([k, v])=> el.setAttribute(k, v));
    document.head.appendChild(el);
  };
  balise('meta', { id:'curieux-pwa-pose', name:'curieux-pwa', content:'1' });

  // Quel manifeste annoncer ?
  //
  // Le manifeste de l'équipe démarre sur "/", c'est-à-dire l'écran de
  // connexion : l'annoncer sur une page ouverte par lien personnel donnerait
  // à la personne une icône inutilisable. Ces pages reçoivent donc un
  // manifeste fabriqué pour elles, dont l'adresse de départ est leur propre
  // lien — voir api/manifeste.js.
  // Les libellés doivent rester accordés à ceux de api/manifeste.js : c'est le
  // nom que la personne verra sous l'icône.
  const CURIEUX_PAGES_LIEN_PERSONNEL = {
    'mon-espace.html':        { param:'token', court:'Mon espace' },
    'mes-infos.html':         { param:'token', court:'Mes infos' },
    'dispo-titulaire.html':   { param:'token', court:'Mes dispos' },
    'mes-remplacants.html':   { param:'token', court:'Remplaçants' },
    'technique-partage.html': { param:'jeton', court:'Technique' },
    'fiche-technique.html':   { param:'jeton', court:'Fiche tech' },
  };

  const params = new URLSearchParams(location.search);
  const page = location.pathname.split('/').pop() || '';
  const def = Object.prototype.hasOwnProperty.call(CURIEUX_PAGES_LIEN_PERSONNEL, page)
    ? CURIEUX_PAGES_LIEN_PERSONNEL[page] : null;
  const nomParam = def ? def.param : null;
  const jeton = nomParam ? (params.get(nomParam) || '') : '';

  // Le jeton doit être plausible avant d'être recopié dans une adresse : les
  // jetons de l'app sont alphanumériques, tout le reste est écarté.
  const href = (jeton && /^[A-Za-z0-9_-]{1,128}$/.test(jeton))
    ? `/api/manifeste?page=${encodeURIComponent(page)}&jeton=${encodeURIComponent(jeton)}`
    : (nomParam ? null : '/manifest.json');

  if(href) balise('link', { id:'curieux-manifest', rel:'manifest', href });
  balise('link', { rel:'apple-touch-icon', href:'/assets/images/apple-touch-icon.png' });

  // Couleur de la barre système, accordée au thème clair/sombre de l'app.
  balise('meta', { name:'theme-color', content:'#791649', media:'(prefers-color-scheme: light)' });
  balise('meta', { name:'theme-color', content:'#141617', media:'(prefers-color-scheme: dark)' });

  // Plein écran une fois installée. La balise "apple-" reste nécessaire :
  // iOS ne lit pas encore l'équivalent standard.
  balise('meta', { name:'mobile-web-app-capable', content:'yes' });
  balise('meta', { name:'apple-mobile-web-app-capable', content:'yes' });
  balise('meta', { name:'apple-mobile-web-app-status-bar-style', content:'black-translucent' });
  balise('meta', { name:'apple-mobile-web-app-title', content: def ? def.court : 'Curieux' });

  if(!('serviceWorker' in navigator)) return;
  // Sur file:// (ouverture locale d'un fichier) l'enregistrement échoue : on
  // s'abstient plutôt que de polluer la console.
  if(location.protocol !== 'https:' && location.hostname !== 'localhost') return;

  window.addEventListener('load', ()=>{
    navigator.serviceWorker.register('/sw.js').catch((e)=>{
      console.warn('[Curieux] service worker non enregistré :', e && e.message);
    });
  });

  // Quand une nouvelle version est déployée, on recharge une seule fois pour
  // que l'équipe ne reste pas sur une version ancienne sans le savoir.
  //
  // Le garde-fou compte : à la toute première visite, le service worker prend
  // le contrôle de la page (clients.claim) et déclenche le même événement.
  // Sans ce test, chaque nouvel arrivant subirait un rechargement gratuit.
  const avaitControleur = !!navigator.serviceWorker.controller;
  let rechargee = false;
  navigator.serviceWorker.addEventListener('controllerchange', ()=>{
    if(!avaitControleur || rechargee) return;
    rechargee = true;
    location.reload();
  });
}

// --- Accès admin par vrai compte Supabase (remplace l'ancien mot de passe
// partagé "admin" en clair). Un compte doit en plus figurer dans la table
// infos_sociales_admins pour être reconnu — même liste de confiance que la
// zone infos sociales, voir migrations.sql / SETUP_LOCAL.md pour y ajouter
// quelqu'un. Redirige vers admin-login.html si la session est absente ou
// non autorisée. ---

// Appelé depuis le <head>, avant que <body> existe : masque la page tout de
// suite pour éviter un flash de contenu avant la vérification de session.
function hideCurieuxPageUntilAuth(){
  const style = document.createElement('style');
  style.id = 'curieux-lock-hide';
  style.textContent = 'body{visibility:hidden !important;}';
  document.head.appendChild(style);
}

// Appelé une fois <body> chargé : vérifie session + appartenance (tout rôle)
// à infos_sociales_admins, révèle la page si tout est bon, sinon redirige.
// Utilisé par les pages admin courantes (annuaires, tournées, dispos...).
async function requireAdminAuth(){
  try{
    const session = await CurieuxDB.getSession();
    if(session && await CurieuxDB.hasAppAccess()){
      const hideStyle = document.getElementById('curieux-lock-hide');
      if(hideStyle) hideStyle.remove();
      try{ injectAdminLogoutButton(session.user.email); }catch(e){}
      return;
    }
  }catch(e){ console.warn('[requireAdminAuth]', e); }
  const here = location.pathname.split('/').pop() + location.search;
  location.replace('admin-login.html?redirect=' + encodeURIComponent(here));
}

// Même chose, mais exige le rôle 'admin' précisément (pas juste 'user') —
// utilisé par les zones réservées : infos sociales, tableau de bord admin.
// Passe level=admin à admin-login.html : SANS ça, un compte 'user' connecté
// (donc avec hasAppAccess() vrai) serait renvoyé en boucle infinie vers cette
// page par admin-login.html, qui le croirait autorisé.
async function requireSuperAdminAuth(){
  try{
    const session = await CurieuxDB.getSession();
    if(session && await CurieuxDB.isSuperAdmin()){
      const hideStyle = document.getElementById('curieux-lock-hide');
      if(hideStyle) hideStyle.remove();
      try{ injectAdminLogoutButton(session.user.email); }catch(e){}
      return;
    }
  }catch(e){ console.warn('[requireSuperAdminAuth]', e); }
  const here = location.pathname.split('/').pop() + location.search;
  location.replace('admin-login.html?level=admin&redirect=' + encodeURIComponent(here));
}

// Direction technique (août 2026) : réservé aux comptes 'admin' + aux comptes
// explicitement désignés (infos_sociales_admins.direction_technique), gérés
// depuis admin-dashboard.html. Un compte 'user' sans ce droit, bien
// qu'ayant accès au reste de l'app, est renvoyé vers l'accueil plutôt que
// vers la page de connexion — il EST connecté, il n'a juste pas ce droit-là.
async function requireDirectionTechniqueAuth(){
  try{
    const session = await CurieuxDB.getSession();
    if(session){
      if(!(await CurieuxDB.hasAppAccess())){
        const here = location.pathname.split('/').pop() + location.search;
        location.replace('admin-login.html?redirect=' + encodeURIComponent(here));
        return;
      }
      if(await CurieuxDB.hasDirectionTechniqueAccess()){
        const hideStyle = document.getElementById('curieux-lock-hide');
        if(hideStyle) hideStyle.remove();
        try{ injectAdminLogoutButton(session.user.email); }catch(e){}
        return;
      }
      location.replace('accueil.html');
      return;
    }
  }catch(e){ console.warn('[requireDirectionTechniqueAuth]', e); }
  const here = location.pathname.split('/').pop() + location.search;
  location.replace('admin-login.html?redirect=' + encodeURIComponent(here));
}

// Bouton de déconnexion — inséré comme dernière pastille de .page-nav (même
// style que les autres liens de nav) plutôt qu'en coin de page fixe : un
// élément position:fixed superposait le texte du nav sur les pages où celui-ci
// s'étend jusqu'à la droite de l'écran (toutes les pages admin courantes).
function injectAdminLogoutButton(email){
  if(document.getElementById('curieuxAdminLogout')) return;
  const nav = document.querySelector('.page-nav');
  const btn = document.createElement('button');
  btn.type = 'button';
  btn.id = 'curieuxAdminLogout';
  btn.title = 'Connecté·e en tant que ' + email;
  btn.textContent = 'Déconnexion';
  // Depuis la refonte, .page-nav est le groupe d'actions du bandeau prune : le
  // bouton y prend le rendu des commandes du bandeau (contour clair sur prune)
  // au lieu du gris sur blanc, illisible à cet endroit.
  const dansBandeau = nav && nav.closest('.co-topbar');
  if(dansBandeau){
    btn.className = 'co-topbar-btn';
    nav.appendChild(btn);
  } else if(nav){
    // Le sélecteur .page-nav > a.ghost de chaque page ne cible que des <a> —
    // ce bouton reprend donc le même rendu directement en style inline.
    btn.style.cssText = 'color:var(--muted); font-weight:700; font-size:12.5px; background:transparent; border:none; padding:7px 13px; border-radius:20px; cursor:pointer; font-family:inherit; white-space:nowrap; transition:background .15s, color .15s;';
    btn.addEventListener('mouseenter', ()=>{ btn.style.background = 'var(--border)'; btn.style.color = 'var(--text)'; });
    btn.addEventListener('mouseleave', ()=>{ btn.style.background = 'transparent'; btn.style.color = 'var(--muted)'; });
    nav.appendChild(btn);
  } else {
    btn.style.cssText = 'position:fixed; top:10px; right:12px; z-index:9998; font-family:\'Host Grotesk\',-apple-system,BlinkMacSystemFont,sans-serif; font-size:12px; font-weight:700; color:var(--muted,#8a7686); background:var(--card,#fff); border:1px solid var(--border,#f0dbe6); border-radius:20px; padding:7px 13px; cursor:pointer;';
    document.body.appendChild(btn);
  }
  btn.addEventListener('click', async ()=>{
    await CurieuxDB.signOut();
    location.href = 'admin-login.html';
  });
}

// Petit onglet "Signaler un bug", présent sur TOUTES les pages (admin comme
// publiques par lien perso) — pas besoin de compte, la table bug_reports est
// ouverte en écriture à la clé anonyme (voir migrations.sql). Les messages
// arrivent ensuite dans la console admin (admin-dashboard.html), lisible
// uniquement par les comptes 'admin'.
// Positionné en onglet vertical sur le bord droit de l'écran, en bas
// (position:fixed, bottom:110px) plutôt qu'au milieu (top:50%) — un onglet
// centré verticalement finissait immanquablement par recouvrir le contenu
// des cartes au scroll sur les pages longues. bottom:110px laisse une marge
// au-dessus de la barre de sauvegarde pleine largeur (~70-100px avec l'encoche)
// de dispo-titulaire.html/mes-infos.html/mes-remplacants.html quand elle est visible.
function injectBugReportWidget(){
  if(!document.body){
    document.addEventListener('DOMContentLoaded', injectBugReportWidget);
    return;
  }
  if(document.getElementById('curieuxBugWidget')) return;

  const FONT = "'Host Grotesk',-apple-system,BlinkMacSystemFont,\"Segoe UI\",Roboto,Helvetica,Arial,sans-serif";

  const tab = document.createElement('button');
  tab.type = 'button';
  tab.id = 'curieuxBugWidget';
  tab.title = 'Signaler un bug, une amélioration ou une incohérence';
  // width:max-content — sans ça, une page dont le CSS a une règle générique
  // "button{width:100%}" (ex: admin-login.html, pensée pour son propre bouton
  // "Se connecter") étire cet onglet sur toute la largeur de l'écran : les
  // styles inline gagnent en cascade, mais seulement pour les propriétés
  // qu'ils déclarent vraiment.
  tab.style.cssText = `position:fixed; bottom:110px; right:0; z-index:9997;
    display:flex; align-items:center; gap:6px; width:max-content; font-family:${FONT}; font-size:12px; font-weight:700;
    color:var(--muted,#8a7686); background:var(--card,#fff); border:1px solid var(--border,#f0dbe6);
    border-right:none; border-radius:10px 0 0 10px; padding:10px 12px; cursor:pointer;
    box-shadow:-2px 2px 10px rgba(20,15,10,.08); transition:background .15s, color .15s;`;
  tab.innerHTML = '<svg width="14" height="14" viewBox="0 0 24 24" style="flex-shrink:0;"><path d="M4 5.5a2 2 0 0 1 2-2h12a2 2 0 0 1 2 2v9a2 2 0 0 1-2 2H9l-4.5 4V16.5H6a2 2 0 0 1-2-2v-9z" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round"></path><line x1="12" y1="7.5" x2="12" y2="11.5" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"></line><circle cx="12" cy="14" r="1" fill="currentColor"></circle></svg><span>Un retour ?</span>';
  tab.addEventListener('mouseenter', ()=>{ tab.style.color = 'var(--accent-dark,#5a1037)'; tab.style.borderColor = 'var(--accent,#791649)'; });
  tab.addEventListener('mouseleave', ()=>{ tab.style.color = 'var(--muted,#8a7686)'; tab.style.borderColor = 'var(--border,#f0dbe6)'; });

  const TYPES = [
    { value:'bug', label:'Bug' },
    { value:'amelioration', label:'Amélioration' },
    { value:'incoherence', label:'Incohérence' },
  ];
  const typeBtnStyle = 'flex:1; background:var(--bg,#FCF2F0); color:var(--muted,#8a7686); border:1px solid var(--border,#f0dbe6); border-radius:8px; padding:8px 6px; font-size:12px; font-weight:700; cursor:pointer; font-family:inherit; transition:background .15s, color .15s, border-color .15s;';
  const typeBtnActiveStyle = 'flex:1; background:var(--accent-solid,#791649); color:#fff; border:1px solid var(--accent-solid,#791649); border-radius:8px; padding:8px 6px; font-size:12px; font-weight:700; cursor:pointer; font-family:inherit;';

  const overlay = document.createElement('div');
  overlay.id = 'curieuxBugOverlay';
  overlay.style.cssText = 'display:none; position:fixed; inset:0; background:rgba(20,15,10,.5); align-items:center; justify-content:center; padding:20px; z-index:9998;';
  overlay.innerHTML = `
    <div style="background:var(--card,#fff); color:var(--text,#141617); border-radius:14px; padding:22px; max-width:420px; width:100%; box-shadow:0 20px 60px rgba(0,0,0,.25); font-family:${FONT};">
      <h2 style="font-size:16px; margin:0 0 6px; font-weight:800;">Signaler un bug, une amélioration ou une incohérence</h2>
      <p style="font-size:12px; color:var(--muted,#8a7686); margin:0 0 12px; line-height:1.4;">Ça arrive directement dans la console d'administration, avec les autres retours du même genre.</p>
      <div id="curieuxBugTypes" style="display:flex; gap:6px; margin-bottom:12px;">
        ${TYPES.map(t=> `<button type="button" data-bug-type="${t.value}" style="${t.value === 'bug' ? typeBtnActiveStyle : typeBtnStyle}">${t.label}</button>`).join('')}
      </div>
      <textarea id="curieuxBugMessage" rows="5" maxlength="2000" style="width:100%; box-sizing:border-box; padding:9px 11px; border:1px solid var(--border,#f0dbe6); border-radius:8px; font-size:14px; font-family:inherit; background:var(--bg,#FCF2F0); color:var(--text,#141617); resize:vertical;" placeholder="Ex : le bouton Exporter en PDF ne répond plus sur la page Tournées…"></textarea>
      <div id="curieuxBugStatus" style="font-size:12px; min-height:1.2em; margin-top:6px;"></div>
      <div style="display:flex; justify-content:flex-end; gap:8px; margin-top:14px;">
        <button type="button" id="curieuxBugCancel" style="background:transparent; border:none; color:var(--muted,#8a7686); font-weight:700; font-size:13px; padding:9px 14px; border-radius:8px; cursor:pointer; font-family:inherit;">Annuler</button>
        <button type="button" id="curieuxBugSend" style="background:var(--accent-solid,#791649); color:#fff; border:none; font-weight:800; font-size:13px; padding:9px 16px; border-radius:8px; cursor:pointer; font-family:inherit;">Envoyer</button>
      </div>
    </div>
  `;

  document.body.appendChild(tab);
  document.body.appendChild(overlay);

  const textarea = overlay.querySelector('#curieuxBugMessage');
  const status = overlay.querySelector('#curieuxBugStatus');
  const sendBtn = overlay.querySelector('#curieuxBugSend');
  const cancelBtn = overlay.querySelector('#curieuxBugCancel');
  const typeBtns = Array.from(overlay.querySelectorAll('[data-bug-type]'));
  let selectedType = 'bug';

  typeBtns.forEach(btn=>{
    btn.addEventListener('click', ()=>{
      selectedType = btn.dataset.bugType;
      typeBtns.forEach(b=> b.style.cssText = b.dataset.bugType === selectedType ? typeBtnActiveStyle : typeBtnStyle);
    });
  });

  function openOverlay(){
    overlay.style.display = 'flex';
    status.textContent = '';
    textarea.value = '';
    selectedType = 'bug';
    typeBtns.forEach(b=> b.style.cssText = b.dataset.bugType === selectedType ? typeBtnActiveStyle : typeBtnStyle);
    sendBtn.disabled = false;
    sendBtn.textContent = 'Envoyer';
    setTimeout(()=> textarea.focus(), 0);
  }
  function closeOverlay(){ overlay.style.display = 'none'; }

  tab.addEventListener('click', openOverlay);
  cancelBtn.addEventListener('click', closeOverlay);
  overlay.addEventListener('click', (e)=>{ if(e.target === overlay) closeOverlay(); });
  document.addEventListener('keydown', (e)=>{ if(e.key === 'Escape' && overlay.style.display !== 'none') closeOverlay(); });

  sendBtn.addEventListener('click', async ()=>{
    const message = textarea.value.trim();
    if(!message){
      status.textContent = "Écris un message avant d'envoyer.";
      status.style.color = 'var(--danger,#a5313f)';
      return;
    }
    sendBtn.disabled = true;
    sendBtn.textContent = 'Envoi…';
    const page = location.pathname.split('/').pop() || 'accueil.html';
    const { error } = await CurieuxDB.reportBug(message, page, selectedType);
    if(error){
      status.textContent = "Erreur d'envoi — réessaie.";
      status.style.color = 'var(--danger,#a5313f)';
      sendBtn.disabled = false;
      sendBtn.textContent = 'Envoyer';
      return;
    }
    status.textContent = '✓ Message envoyé, merci !';
    status.style.color = 'var(--ok,#2f8f5b)';
    setTimeout(closeOverlay, 1200);
  });
}

// Enregistre Host Grotesk (police de labeur de la charte) dans un document jsPDF sous le nom 'Host'.
function registerHostFont(doc){
  doc.addFileToVFS('HostGrotesk-Regular.ttf', HOST_REGULAR_B64);
  doc.addFont('HostGrotesk-Regular.ttf', 'Host', 'normal');
  doc.addFileToVFS('HostGrotesk-Bold.ttf', HOST_BOLD_B64);
  doc.addFont('HostGrotesk-Bold.ttf', 'Host', 'bold');
  doc.setFont('Host', 'normal');
}

// En-tête de page PDF commun : bandeau clair, filigrane du logo Curieux, titre à droite.
function drawCurieuxPdfHeader(doc, pageWidth, title, headerH){
  headerH = headerH || 20;
  doc.setFillColor(253, 227, 238);
  doc.rect(0, 0, pageWidth, headerH, 'F');
  doc.setFillColor(121, 22, 73);
  doc.rect(0, headerH, pageWidth, 1, 'F');
  try{
    const props = doc.getImageProperties(CURIEUX_LOGO_PRUNE_PNG);
    const ratio = props.width / props.height;
    let wmH = headerH * 0.6, wmW = wmH * ratio;
    const maxW = pageWidth * 0.5;
    if(wmW > maxW){ wmW = maxW; wmH = wmW / ratio; }
    doc.saveGraphicsState();
    doc.setGState(new doc.GState({ opacity: 0.9 }));
    doc.addImage(CURIEUX_LOGO_PRUNE_PNG, 10, (headerH - wmH)/2, wmW, wmH);
    doc.restoreGraphicsState();
  }catch(e){}
  doc.setFont('Host', 'bold');
  doc.setFontSize(11);
  doc.setTextColor(121, 22, 73);
  doc.text(title, pageWidth - 12, headerH/2 + 3, { align:'right' });
  doc.setTextColor(20, 22, 23);
}

// --- Mode nuit automatique (suit le mode sombre/clair du système, pas l'heure) ---
let __curieuxThemeListenerAdded = false;
function applyAutoTheme(){
  // La refonte ajoute une bascule manuelle dans le bandeau (voir nav.js). Un
  // choix explicite l'emporte sur le système : sans ça, le premier appel de
  // applyAutoTheme() — au chargement, ou toutes les 5 min sur les pages qui le
  // rappellent — écrasait aussitôt la bascule de l'utilisateur.
  let choix = '';
  try{ choix = localStorage.getItem('curieuxTheme') || ''; }catch(e){}
  const dark = choix ? choix === 'dark'
    : !!(window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches);
  document.documentElement.setAttribute('data-theme', dark ? 'dark' : 'light');
  try{ applyBrandLogo(); }catch(e){}
  // Le navigateur/OS peut basculer le thème pendant que la page est ouverte (heure
  // programmée du système, bascule manuelle) : on écoute le changement pour suivre en
  // direct, plutôt que de dépendre du polling setInterval(applyAutoTheme, ...) existant.
  if(window.matchMedia && !__curieuxThemeListenerAdded){
    __curieuxThemeListenerAdded = true;
    window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', applyAutoTheme);
  }
}
